# try: quadruple family = all 14 weight-4 words of the Hamming code generated by lines (with 0)
def sets_for(family):
    S2=set()
    for qd in family:
        for signs in itertools.product([1,-1], repeat=4):
            v=[0]*8
            for idx,s in zip(qd,signs): v[idx]=s
            S2.add(tuple(v))
    for i in range(8):
        for s in (1,-1):
            v=[0]*8; v[i]=2*s; S2.add(tuple(v))
    return S2
