# build binary [8,4,4] code from the 7 lines (indices 1..7) + parity at 0
import itertools as it
vecs=[]
for L in lines:
    v=[0]*8
    for t in L: v[t]=1
    v[0]=1 if sum(v)%2 else 0
    vecs.append(v)
# generate span
span=set()
for coef in it.product([0,1], repeat=len(vecs)):
    w=[0]*8
    for c,v in zip(coef,vecs):
        if c: w=[(x+y)%2 for x,y in zip(w,v)]
    span.add(tuple(w))
print('code size', len(span), 'weight distr', sorted({sum(w) for w in span}))
w4=[w for w in span if sum(w)==4]
print('weight-4 words', len(w4))
S2=sets_for([tuple(i for i in range(8) if w[i]) for w in w4])
print('|S2|', len(S2), 'closed', all(mul2(X,Y) in S2 for X in S2 for Y in S2))
